python3 -I -m json.tool output/annotation/sha512sum.json >/dev/null && echo JSON_OK && python3 -I -m py_compile output/sha512sum.py output/annotation/*.py && echo COMPILE_OK
# stub caruca to load the spec and cross-check with the binary
T=$(mktemp -d); mkdir -p $T/caruca/ir; touch $T/caruca/__init__.py $T/caruca/ir/__init__.py
cat > $T/caruca/ir/syntax.py <<'EOF'
import enum
class Arity(enum.Enum):
    OPTIONAL=1; ZERO_OR_ONE=1; EXACTLY_ONE=2; EXACTLY_TWO=3; ZERO_OR_MORE=4; AT_LEAST_ONE=5; ONE_OR_MORE=5
SyntaxSpecification=list
class Node:
    def __init__(self, flag=None, alias=(), **kw): self.flag=flag; self.alias=list(alias); self.kw=kw
class Flag(Node):
    def __init__(self, flag, alias=()): super().__init__(flag, alias)
for n in "Path Integer Int Number String Selection List Regex Glob Separator Char Other".split():
    globals()[n]=type(n,(Node,),{})
EOF
cd $T && printf x > f && PYTHONPATH=$T python3 -I - <<'EOF'
import json, subprocess, string, importlib.util, sys
spec = importlib.util.spec_from_file_location("s", "/home/tirandagan.guest/naive-arm/output/sha512sum.py"); m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
opts = m.sha512sum_syntax_spec[0][0]
spellings = sorted({s for n in opts for s in [n.flag]+n.alias})
j = json.load(open("/home/tirandagan.guest/naive-arm/output/annotation/sha512sum.json"))
jspell = sorted({s for e in j["flag"] for s in (e if isinstance(e,list) else [e])})
assert spellings == jspell, (spellings, jspell)
assert all(type(n).__name__=="Flag" for n in opts)
def rc(*a): return subprocess.run(["sha512sum",*a],capture_output=True,text=True)
bad=[]
for s in spellings:
    if s in ("--help","--version"): r=rc(s)
    elif s in ("--ignore-missing","--quiet","--status","--strict","-w","--warn"): r=rc("-c",s,"/dev/null")
    else: r=rc(s,"f")
    if r.returncode!=0 and "invalid option" in r.stderr or "unrecognized" in r.stderr: bad.append(s)
print("spec spellings rejected by binary:", bad)
extra=[c for c in string.ascii_letters+string.digits if "invalid option" not in rc("-"+c,"f").stderr and "-"+c not in spellings]
print("short letters accepted but not in spec:", extra)
EOF

